import {neutralAdjustment,adjustmentTarget,mutateAdjustment} from './adjustments.js';
export function initAdjustmentUI({$,getBoard,blocked,preview,commit,status}){
 const dialog=$('adjustment-editor'),form=$('adjustment-form');let draft=null;
 const fields=[['hue','Hue °',-180,180,1],['saturation','Saturation %',-100,100,1],['lightness','Lightness %',-100,100,1],['black','Input black',0,254,1],['white','Input white',1,255,1],['gamma','Midtones (gamma)',.1,10,.05],['outBlack','Output black',0,255,1],['outWhite','Output white',0,255,1]];
 for(const [key,name,min,max,step]of fields){const label=document.createElement('label');label.textContent=name;label.htmlFor='adjust-'+key;const row=document.createElement('div');row.className='adjustment-value';for(const kind of ['range','number']){const input=document.createElement('input');input.type=kind;input.min=min;input.max=max;input.step=step;input.id='adjust-'+key+(kind==='number'?'-number':'');input.setAttribute('aria-label',name+(kind==='number'?' value':''));input.addEventListener('input',()=>{const value=input.value;for(const other of row.querySelectorAll('input'))if(other!==input)other.value=value;update();});row.append(input);}label.append(row);$('adjustment-fields').append(label);}
 function values(){const a={};for(const [key]of fields){const v=$('adjust-'+key+'-number').value;if(v==='')throw Error('Enter all adjustment values');a[key]=Number(v);}return a;}
 function populate(a){for(const [key]of fields)for(const suffix of ['','-number'])$('adjust-'+key+suffix).value=a[key];}
 function update(){if(!draft)return;try{if(getBoard()!==draft.base)throw Error('Board changed · cancel and reopen adjustments');const board=structuredClone(draft.base),a=values();mutateAdjustment(board,draft.id,a);preview(board);draft.value=a;$('adjustment-error').textContent='';$('adjustment-apply').disabled=false;}catch(e){$('adjustment-error').textContent=e.message;$('adjustment-apply').disabled=true;}}
 function cancel(){if(!draft)return;draft=null;dialog.close();preview(null);status('Colour adjustment cancelled · original artwork restored');}
 form.addEventListener('submit',e=>{e.preventDefault();if(!draft)return;update();if($('adjustment-apply').disabled)return;try{if(getBoard()!==draft.base)throw Error('Adjustment is stale');const {id,value,base}=draft;commit(id,value,base);draft=null;dialog.close();preview(null);status('Colour adjustment saved · Undo restores prior appearance');}catch(err){$('adjustment-error').textContent=err.message;}});
 $('adjustment-cancel').onclick=cancel;dialog.addEventListener('cancel',e=>{e.preventDefault();cancel();});window.addEventListener('blur',cancel);
 $('adjustment-reset').onclick=()=>{populate(neutralAdjustment);update();};
 return {editing:()=>!!draft,cancel,open(id){if(blocked())return;try{const base=getBoard(),{node,folder}=adjustmentTarget(base,id);const board=structuredClone(base);mutateAdjustment(board,id,node.adjustment||neutralAdjustment);draft={id,base,value:structuredClone(node.adjustment||neutralAdjustment)};$('adjustment-target').textContent=(folder?'Group: ':'Layer: ')+node.name;$('adjustment-group-note').hidden=!folder;populate(draft.value);$('adjustment-error').textContent='';$('adjustment-apply').disabled=false;dialog.showModal();update();}catch(e){draft=null;status(e.message,true);}}};
}
